import { bindSetIcon, renderSetIcon } from "../icon-set-core.js";

export const definition = {
  "name": "folder-open",
  "category": "Files",
  "viewBox": "0 0 24 24",
  "mode": "stroke",
  "strokeWidth": 2,
  "motion": "file",
