};

export const meta = {
  "slug": "lucide-folder-open",
  "family": "lucide",
  "name": "folder-open",
  "category": "Files",
  "motion": "file",
  "component": "createLucideFolderOpenIcon"
};

export function createLucideFolderOpenIcon(root, options = {}) {
  let current = { ...options };
  const render = () => {
    root.innerHTML = renderSetIcon(definition, current);
  };
  render();
  const controller = bindSetIcon(root, definition, () => current);
  return {
    play: controller.play,
    reset: controller.reset,
    destroy: controller.destroy,
    update(next = {}) {
      current = { ...current, ...next };
      render();
    },
    get observed() {
      return controller.observed;
    },
  };
}
